import {storyOpening,aiPage,chapterFrame} from './external-journey-frame.js?v=20260921-proof2';
import {vendorConfig} from './vendor-config.js?v=20260920-rewards1';
import {cases} from './workshop.js';
const e=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));

const stages=[
  ['Discover','A guest chooses Harborline Rewards from the booking experience.','Keep the entry branded and explain why an account improves the stay.'],
  ['Register','Elena creates one customer identity and verifies her sign-in method.','Collect only the attributes needed now; ask for more when the experience needs them.'],
  ['Consent','She chooses communication and personalization preferences.','Store purpose, version and time so consent can be changed and proven later.'],
  ['Use','The application recognizes Elena across booking and rewards experiences.','Use a stable subject identifier and keep profile data separate from authorization.'],
  ['Step up','A points transfer requires stronger assurance.','Apply MFA to the sensitive action while keeping ordinary browsing simple.'],
  ['Recover','Elena regains access without a support agent seeing her secret.','Use configured self-service recovery and record the event.'],
  ['Change','She updates preferences or asks Harborline to close the relationship.','Coordinate profile, consent, retention and downstream application records.'],
  ['Prove','The team correlates sign-in, consent and application decisions.','Show the complete decision trail without exposing unnecessary customer data.']
];

const proof=[
  ['User flow association','Show the rewards application is associated with the intended sign-up and sign-in user flow.'],
  ['Collected attributes','Confirm the flow requests only the prepared customer attributes.'],
  ['Consent record','Show purpose, policy version, customer choice and timestamp in the application record.'],
  ['Step-up result','Correlate the sensitive points action with the required authentication assurance.'],
  ['Lifecycle evidence','Show recovery, preference change or prepared account-closure evidence.']
];

let view='experience';
let scene='welcome';
let selectedStage=0;
const checked=new Set();

function orbit(){return `<div class="loyalty-orbit" aria-label="Elena’s customer identity story"><div class="loyalty-person"><span>HARBORLINE REWARDS MEMBER</span><strong>Elena Torres</strong><small>One customer identity · choices she controls</small></div><div class="loyalty-story-beat"><b>01</b><span>Join</span><small>Branded sign-up</small></div><div class="loyalty-story-beat"><b>02</b><span>Be known</span><small>Progressive profile</small></div><div class="loyalty-story-beat"><b>03</b><span>Move value</span><small>Step-up protection</small></div><div class="loyalty-story-beat"><b>04</b><span>Stay in control</span><small>Consent + recovery</small></div></div>`;}

function journey(){const active=view==='experience'?(scene==='welcome'?0:3):view==='architecture'?selectedStage:7;return `<div class="vendor-journey loyalty-journey" aria-label="Elena’s customer identity lifecycle"><span>CUSTOMER JOURNEY</span>${stages.map((stage,index)=>`<button data-loyalty="journey" data-index="${index}" class="${index===active?'active':''}" ${index===active?'aria-current="step"':''}><b>${String(index+1).padStart(2,'0')}</b><small>${e(stage[0])}</small></button>`).join('')}</div>`;}

function welcome(){if(scene==='profile')return profile();return `<div class="loyalty-preview-note live"><span>LIVE REWARDS SITE CONNECTED</span> Open the real customer experience, then use this workshop preview to explain the business outcome</div><section class="loyalty-portal"><div class="loyalty-welcome"><div class="loyalty-welcome-copy"><span class="loyalty-kicker">MEET ELENA TORRES · HARBORLINE GUEST</span><h2>A welcome that remembers.<br><em>A customer who stays in control.</em></h2><p>Elena wants faster booking and useful rewards without giving up control of her identity, preferences or account.</p><div class="loyalty-benefits"><span>Branded registration</span><span>Progressive profile</span><span>Consent</span><span>Step-up security</span></div></div><div class="loyalty-entry"><div class="loyalty-mark">H</div><span class="loyalty-kicker">HARBORLINE REWARDS</span><h3>Travel feels better when it knows you.</h3><p>Create or use your Harborline customer account. Your choices shape the experience and can be changed at any time.</p><a class="loyalty-live" href="${e(vendorConfig.rewardsPortalUrl)}" target="_blank" rel="noopener noreferrer">Open live Rewards site ↗</a><button class="loyalty-preview-button" data-loyalty="preview">Explore Elena’s member view →</button><small>Use private credentials only in the connected application. Verify the sign-in path before presenting.</small></div></div></section>`;}

function profile(){return `<div class="loyalty-preview-note"><span>ILLUSTRATIVE MEMBER VIEW</span> This preview teaches the business outcome; tenant and API evidence belong in the live demonstration</div><section class="loyalty-member"><header><div><span class="loyalty-kicker">HARBORLINE REWARDS</span><h2>Welcome back, Elena.</h2><p>Gold member · 42,680 points</p></div><button data-loyalty="welcome">Back to welcome</button></header><div class="loyalty-stats"><article><small>PROFILE</small><strong>Travel preferences</strong><span>3 details completed progressively</span></article><article><small>CONSENT</small><strong>Your choices</strong><span>Email on · personalization on</span></article><article><small>ASSURANCE</small><strong>Standard session</strong><span>Step-up before points transfer</span></article></div><div class="loyalty-actions"><article><span>EVERYDAY ACTION</span><h3>Book a stay</h3><p>Elena can browse, book and apply points with the current session.</p><b>AVAILABLE</b></article><article class="sensitive"><span>SENSITIVE ACTION</span><h3>Transfer 20,000 points</h3><p>The application asks for stronger authentication before value leaves the account.</p><b>STEP-UP REQUIRED</b></article><article><span>CUSTOMER CONTROL</span><h3>Privacy &amp; preferences</h3><p>Elena can change communication choices and review account controls.</p><b>MANAGE</b></article></div><aside><strong>The teaching moment</strong><p>A successful sign-in establishes identity. The application still decides when stronger assurance, consent or current business context is required.</p><a href="#elena/architecture">Reveal the control path →</a></aside></section>`;}

function architecture(){const stage=stages[selectedStage];const systems=[['01','Customer app','Branded entry','Harborline controls the experience and starts OIDC.'],['02','External ID','Sign up + sign in','The user flow authenticates Elena and issues a stable subject.'],['03','Trust check','Enrich + validate','An optional extension can validate or enrich approved attributes.'],['04','Token','Identity contract','The application validates issuer, audience, expiry and claims.'],['05','Rewards API','Consent + value','The API enforces points, preferences and action-level policy.']];return `<section class="loyalty-architecture"><header><div><span class="loyalty-kicker">REFERENCE ARCHITECTURE · ELENA’S JOURNEY</span><h2>Identity gets Elena in.<br><em>The application decides what happens next.</em></h2><p>Read left to right. Every handoff has one clear owner and one decision to prove.</p></div><span>VERIFY EACH CONTROL IN THE TENANT</span></header><div class="loyalty-boundary-legend"><span>CUSTOMER EXPERIENCE</span><span>MICROSOFT ENTRA EXTERNAL ID</span><span>APPLICATION + DATA</span></div><div class="loyalty-control-flow" aria-label="Customer External ID architecture">${systems.map((system,index)=>`<article class="${index===1?'identity':''} ${index===4?'decision':''}"><b>${system[0]}</b><div class="loyalty-system-icon" aria-hidden="true">${index===0?'↗':index===1?'ID':index===2?'✓':index===3?'◇':'API'}</div><h3>${system[1]}</h3><strong>${system[2]}</strong><p>${system[3]}</p></article>${index<systems.length-1?'<i aria-hidden="true">→</i>':''}`).join('')}</div><div class="loyalty-decision-line"><div><span>AUTHENTICATION</span><strong>Who is Elena?</strong><small>External ID establishes the customer identity and assurance.</small></div><b>≠</b><div><span>AUTHORIZATION</span><strong>May she transfer these points?</strong><small>The rewards API evaluates the action, value and current policy.</small></div></div><div class="loyalty-guardrails"><article><span>IDENTITY</span><strong>Stable customer subject</strong><p>Link rewards data to an immutable subject rather than a changeable email.</p></article><article><span>PROFILE</span><strong>Progressive collection</strong><p>Ask for optional context only when it improves the customer experience.</p></article><article><span>ASSURANCE</span><strong>Step up at the action</strong><p>Require stronger authentication when Elena transfers loyalty value.</p></article><article><span>CONTROL</span><strong>Consent and lifecycle</strong><p>Keep choices, retention and closure evidence with the systems that own them.</p></article></div></section><section class="loyalty-stage"><div><span class="loyalty-kicker">NARRATE STAGE ${String(selectedStage+1).padStart(2,'0')}</span><h3>${e(stage[1])}</h3><p>${e(stage[2])}</p></div><nav aria-label="Explore the customer control path">${stages.map((item,index)=>`<button data-loyalty="stage" data-index="${index}" aria-pressed="${index===selectedStage}"><b>${String(index+1).padStart(2,'0')}</b>${e(item[0])}</button>`).join('')}</nav></section><div class="loyalty-explain"><article><span class="loyalty-kicker">CUSTOMIZE IT</span><h3>Fit the experience to the relationship.</h3><p>Brand the pages, select identity providers, localize language, choose required attributes, connect approved extensions and tune assurance for the customer action.</p></article><article><span class="loyalty-kicker">USE AI WITH CONTROL</span><h3>Explain friction before changing policy.</h3><p>AI can summarize supplied sign-in and application events, find drop-off patterns and draft a reversible recommendation for human approval.</p></article></div>`;}

function evidence(){return `<div class="vendor-proof-head loyalty-proof-head"><div><span class="loyalty-kicker">PROVE THE CUSTOMER OUTCOME</span><h2>Show the experience and the control behind it.</h2><p>Check each item only after presenting the corresponding tenant or application evidence.</p></div><a class="outline" href="https://entra.microsoft.com" target="_blank" rel="noopener noreferrer">Open external tenant ↗</a></div><div class="vendor-evidence-list">${proof.map(([title,description],index)=>`<label class="vendor-evidence"><input type="checkbox" data-loyalty-proof="${index}" ${checked.has(index)?'checked':''}><span><strong>${e(title)}</strong><small>${e(description)}</small></span><em>${checked.has(index)?'Presenter checked':'Not verified here'}</em></label>`).join('')}</div><div class="vendor-proof-summary" role="status">${checked.size} of ${proof.length} checks marked by presenter</div><section class="loyalty-replay"><div><span class="loyalty-kicker">RESET &amp; REPLAY</span><h3>Return Elena to the prepared state.</h3><p>Restore the synthetic preference and points records, remove only the rehearsed test events, clear the customer session and confirm the baseline before presenting again.</p></div><div><span class="loyalty-kicker">CLIENT QUESTION</span><blockquote>Which parts of your customer journey belong in identity, and which must remain enforceable in the application?</blockquote></div></section>`;}

function liveDemo(){return `<section class="external-live-stage"><header><div><span class="loyalty-kicker">TWO LIVE SIDES · ONE CUSTOMER MOMENT</span><h2>Change the control.<br><em>Watch Elena’s experience respond.</em></h2><p>Keep the administrator and customer sessions visible together. Use the guide to explain what changed, why it matters and what evidence proves the outcome.</p></div><button class="primary" data-loyalty="desktop">Launch the two-sided stage →</button></header><div class="external-live-panes"><article><div class="live-pane-top"><span>ADMINISTRATOR</span><b>01</b></div><div class="live-pane-icon">ID</div><h3>External tenant</h3><p>Show the application, user flow, customer record, authentication details and configured policy.</p><ul><li>Confirm the signed-in directory</li><li>Inspect the prepared Elena identity</li><li>Correlate the sign-in event</li></ul><strong>Left side · Harborline administrator</strong></article><div class="external-live-link"><span>CONFIGURE</span><b>→</b><span>EXPERIENCE</span></div><article class="customer"><div class="live-pane-top"><span>CUSTOMER</span><b>02</b></div><div class="live-pane-icon">ET</div><h3>Live Harborline Rewards</h3><p>Run the branded sign-in and compare an everyday action with a sensitive points transfer.</p><ul><li>Sign in as the prepared customer</li><li>Show the normal member experience</li><li>Trigger and explain step-up</li></ul><strong>Right side · connected customer site</strong></article></div><div class="external-live-run"><div><span>RECOMMENDED DEMO SEQUENCE</span><strong>Admin baseline → customer action → policy response → evidence</strong></div><div><a class="outline" href="${e(vendorConfig.rewardsPortalUrl)}" target="_blank" rel="noopener noreferrer">Open live Rewards site ↗</a><button class="outline" data-loyalty="desktop">Open admin + customer sessions ↗</button></div></div></section>`;}

function narrative(){return `<section class="loyalty-narrative"><div><span class="loyalty-kicker">THE COMPLETE JOURNEY</span><h3>Elena receives recognition without losing control.</h3></div><p>Elena discovers Harborline Rewards during booking and registers through a branded External ID user flow. Harborline collects the minimum profile needed to create her account, then progressively asks for preferences when they improve a stay. The rewards application records her consent choices and uses a stable identity subject to find current loyalty data. Everyday booking stays simple; transferring points triggers stronger authentication. Elena can recover access, change preferences and close the relationship. The final evidence joins identity events to application decisions without pretending that authentication alone owns consent, loyalty value or business authorization.</p></section>`;}

export function loyaltyPage(mode='experience'){
  view=['experience','architecture','live','ai','evidence'].includes(mode)?mode:'experience';
  const meta={
    experience:['THE STORY','Know the customer. <em>Respect the boundary.</em>','Follow Elena through branded registration, recognition, step-up, recovery and control.'],
    architecture:['ARCHITECTURE','See the control path. <em>Know who decides.</em>','Separate customer identity, token validation, consent and rewards authorization.'],
    live:['LIVE DEMO','Show both sides. <em>Make the response visible.</em>','Place the external-tenant administrator beside Elena’s customer experience.'],
    ai:['HOW AI HELPS','Find customer friction. <em>Protect the decision.</em>','Use AI to analyze supplied evidence and prepare a reviewable, reversible recommendation.'],
    evidence:['EVIDENCE','Prove the journey. <em>Show the decision trail.</em>','Connect sign-in, consent, assurance and application evidence.']
  }[view];
  const story=storyOpening({headline:'Recognize the customer.<br><em>Keep her choices visible.</em>',summary:'Elena Torres joins Harborline Rewards through a branded customer flow. Her profile grows only when useful, ordinary booking stays simple, valuable actions receive stronger protection and her consent remains changeable.',initials:'ET',name:'Elena Torres',role:'Harborline Rewards member',truth:'A customer identity should make the experience more useful without turning every known fact into access or permanent consent.',portrait:'./assets/personas/elena-torres.webp',outcomes:[['Join','Branded customer sign-up'],['Be known','Progressive profile'],['Move value','Step-up authentication'],['Stay in control','Consent and recovery']]});
  const ai=aiPage({kicker:'AI COPILOT · ELENA’S CUSTOMER EXPERIENCE',title:'Find the friction. <em>Preserve customer choice.</em>',summary:'The assistant can summarize sign-up and application evidence, identify a drop-off pattern and prepare a reversible user-flow recommendation for approval.',buttonAttr:'data-loyalty="desktop"',flow:[['Observe','Read selected sign-up, sign-in and application events.'],['Correlate','Find the step where Elena’s journey breaks.'],['Propose','Draft a branding, attribute or policy adjustment.'],['Approve + run','Apply only the prepared change.'],['Verify + undo','Repeat the customer path and restore baseline.']],inputs:['User-flow configuration and collected attributes','Selected sign-in outcomes and application events','Consent, recovery or step-up evidence supplied for review'],outputs:['A concise friction diagnosis with evidence','A before-and-after configuration preview','The customer result and a verified rollback'],guardrail:'The assistant cannot invent consent, weaken a sensitive-action boundary or treat successful authentication as permission to move loyalty value. The live customer site is connected; agent-driven configuration remains a guided, approval-controlled workflow.'});
  const content=view==='experience'?story+welcome()+narrative():view==='architecture'?architecture():view==='live'?liveDemo():view==='ai'?ai:evidence()+narrative();
  return chapterFrame({classes:'loyalty-shell',accent:'#69e6d4',glow:'#123f56',topline:'MICROSOFT ENTRA EXTERNAL ID · CUSTOMER JOURNEY',name:'ELENA TORRES',role:'REWARDS MEMBER',section:meta[0],title:meta[1],summary:meta[2],route:'elena',view,nav:[['experience','01','The story'],['architecture','02','Architecture'],['live','03','Live demo'],['ai','04','How AI helps'],['evidence','05','Evidence']],context:['EXTERNAL TENANT','Customer account','Progressive profile','Consent + step-up'],status:'LIVE · Harborline Rewards customer site connected',content,footer:'Elena · external tenant customer journey'});
}
export function installLoyaltyEvents(render,onDesktop){document.addEventListener('click',event=>{const button=event.target.closest('[data-loyalty]');if(!button)return;const action=button.dataset.loyalty;if(action==='desktop'){onDesktop();return;}if(action==='journey'){const index=Number(button.dataset.index);if(index===0){scene='welcome';location.hash='#elena/experience';}else if(index===3){scene='profile';location.hash='#elena/experience';}else if(index<7){selectedStage=index;location.hash='#elena/architecture';}else location.hash='#elena/evidence';render();return;}if(action==='preview')scene='profile';if(action==='welcome')scene='welcome';if(action==='stage')selectedStage=Number(button.dataset.index);render();});document.addEventListener('change',event=>{if(!event.target.matches('[data-loyalty-proof]'))return;const index=Number(event.target.dataset.loyaltyProof);event.target.checked?checked.add(index):checked.delete(index);render();document.querySelector(`[data-loyalty-proof="${index}"]`)?.focus();});}

export function elenaGuide(){const step=(action,why,look)=>({action,why,look});return {name:'Elena Torres',time:'Customer journey',title:'Know the customer. Respect the boundary.',job:'Harborline Rewards member',perspective:'Customer experience',liveUrl:vendorConfig.rewardsPortalUrl,liveLabel:'Harborline Rewards',story:'Elena registers once, builds her profile over time and receives stronger protection when she moves loyalty value.',why:'Teach where customer authentication ends and application-owned consent, profile, value and authorization begin.',account:'Prepared Elena External ID test account',domain:'External tenant · verify the administrator profile',cases:cases.filter(c=>[10,11,12,14,32,33,34].includes(c.id)),highlights:['Open the live Harborline Rewards site','Show the associated user flow','Prove a normal and step-up action'],admin:[step('Open the external tenant and verify the rewards application and associated user flow.','The customer experience must use the intended External ID configuration.','Confirm tenant, app registration, redirect URI, user-flow association, identity providers and collected attributes.'),step('Inspect the prepared Elena customer and the application consent record.','Identity profile and business consent have different owners and evidence.','Use the stable customer subject to correlate only the prepared records.'),step('Correlate a normal session with the prepared sensitive-action event.','A successful sign-in does not prove the assurance required to transfer loyalty value.','Match subject, application, timestamp, assurance context and application decision.')],user:[step('Open the live Harborline Rewards site in Elena’s separate browser profile.','Keep the customer experience separate from the administrator session.','Use privately held credentials only in the connected application.'),step('Complete or inspect the prepared registration and preference experience.','Show what is required at sign-up and what is collected later.','Point out branding, language, identity provider and customer choices.'),step('Run the prepared points-transfer or sensitive-profile action.','The audience should see stronger authentication appear at the business moment.','Show the real challenge and resulting application decision only after rehearsing it end to end.')],userTitle:'Experience Elena’s rewards journey',evidence:'Correlate External ID sign-in and user-flow events with application consent, assurance and action records.',caution:'The live Rewards site is connected. Verify its External ID sign-in, prepared Elena data and any protected rewards action before each client session; the embedded member view remains illustrative.',question:'Which parts of your customer journey belong in identity, and which must remain enforceable in the application?'};}
